<?php elseif ($can): ?><div class="card mb-3"><div class="card-header"><i class="bi bi-person-plus"></i> <?= e(t($x ? 'Modifier la fiche' : 'Nouvelle personne')) ?></div><div class="card-body"><form method="post" action="<?= e(url('/ong/fiches')) ?>" class="row g-2"><?= csrf_field() ?>
