  <?= ong_field('matricule', 'Matricule', $x['matricule'] ?? '', 'text', 'required maxlength="30"', 'col-md-2') ?><?= ong_field('full_name', 'Nom et prénom', $x['full_name'] ?? '', 'text', 'required maxlength="150"', 'col-md-3') ?><?= ong_field('position', 'Fonction', $x['position'] ?? '', 'text', 'maxlength="120"', 'col-md-3') ?>
  <?= ong_select('kind', 'Statut', S::PERSONNEL_KINDS, $x['kind'] ?? 'salarie', '', 'col-md-2') ?><?= ong_select('projet_id', 'Projet', ong_opts($projets, 'code', '— (siège)'), $x['projet_id'] ?? '', '', 'col-md-2', false) ?>
