  <div class="col-md-2 d-flex align-items-end gap-1"><button class="btn btn-sm btn-primary"><?= e(t('Enregistrer')) ?></button><?php if ($x): ?><a class="btn btn-sm btn-outline-secondary" href="<?= e(url('/ong/personnel')) ?>"><?= e(t('Annuler')) ?></a><?php endif; ?></div></form>
