<div class="d-flex mb-2"><span class="small text-secondary"><?= count(array_filter($rows, fn ($r) => (int) $r['active'])) ?> <?= e(t('personne(s) en poste')) ?> · <?= e(t('coût mensuel :')) ?> <?= money(array_sum(array_map(fn ($r) => (int) $r['active'] ? (float) $r['monthly_cost'] : 0, $rows))) ?></span>
