<div class="card"><div class="table-responsive"><table class="table table-sm align-middle mb-0 small"><thead><tr><th><?= e(t('Matricule')) ?></th><th><?= e(t('Nom')) ?></th><th><?= e(t('Statut')) ?></th><th><?= e(t('Projet')) ?></th><th><?= e(t('Téléphone')) ?></th><th><?= e(t('Contrat')) ?></th><th class="num"><?= e(t('Coût mensuel')) ?></th><th></th></tr></thead><tbody>
