  <td class="text-nowrap <?= $soon ? 'text-danger fw-semibold' : '' ?>"><?= $s['start_date'] ? e(fdate($s['start_date'], false)) : '' ?><?= $s['end_date'] ? ' → ' . e(fdate($s['end_date'], false)) : '' ?></td><td class="num"><?= money($s['monthly_cost']) ?></td>
  <td class="text-end"><?php if ($can): ?><a class="btn btn-sm btn-outline-secondary" href="<?= e(url('/ong/personnel', ['edit' => $s['id']])) ?>"><i class="bi bi-pencil"></i></a><?php endif; ?></td></tr><?php endforeach; ?>
<?php if (!$rows): ?><tr><td colspan="8" class="text-center text-secondary py-4"><?= e(t('Aucune personne enregistrée.')) ?></td></tr><?php endif; ?></tbody></table></div></div>
